#include "Includes/fizmo/includes.hpp"

template <typename Func>
void benchmark(const std::string& label, Func&& fn, const std::string& true_val, std::ofstream& out) {
    fizmo::time::Stopwatch sw;
    sw.start();
    fizmo::multiprecision::BigFloat result = fn();
    sw.stop();
    std::cout << std::left << std::setw(9) << label << "| " << sw.elapsed().total_milliseconds() << "ms\n";
    std::string approx = result.to_scientific_string();
    out << "[" << label << "]\n"
        << "  approx : " << approx   << "\n"
        << "  actual : " << true_val << "\n\n";
}

